<script>document.addEventListener('DOMContentLoaded',()=>{const list=document.getElementById('specialDatesList'),add=document.getElementById('addSpecialDate');if(!list||!add)return;const row=()=>{const d=document.createElement('div');d.className='special-date-row';d.innerHTML='<input type="date" name="special_date[]" aria-label="Fecha especial"><select name="special_type[]"><option value="closed">Cerrado todo el día</option><option value="hours">Horario especial</option></select><input type="time" name="special_start[]" aria-label="Inicio"><input type="time" name="special_end[]" aria-label="Fin"><button type="button" class="icon-btn danger remove-special-date" title="Quitar fecha"><i class="fa-solid fa-trash"></i></button>';return d};add.addEventListener('click',()=>list.appendChild(row()));list.addEventListener('click',e=>{const b=e.target.closest('.remove-special-date');if(b)b.closest('.special-date-row')?.remove()})});</script>
